static int write_text(const char *path,const char *text){FILE *f=fopen(path,"wb");if(!f)return 0;size_t n=strlen(text);int ok=fwrite(text,1,n,f)==n;if(fclose(f))ok=0;return ok;}
static int pdf(const char *path,const char *text){
 CFStringRef file=CFStringCreateWithCString(NULL,path,kCFStringEncodingUTF8),content=CFStringCreateWithCString(NULL,text,kCFStringEncodingUTF8);if(!file||!content){if(file)CFRelease(file);if(content)CFRelease(content);return 0;}
 CFURLRef url=CFURLCreateWithFileSystemPath(NULL,file,kCFURLPOSIXPathStyle,false);CGRect media=CGRectMake(0,0,595,842);CGContextRef ctx=CGPDFContextCreateWithURL(url,&media,NULL);CFRelease(url);CFRelease(file);if(!ctx){CFRelease(content);return 0;}
 CTFontRef font=CTFontCreateWithName(CFSTR("Helvetica"),11,NULL);CFMutableAttributedStringRef attr=CFAttributedStringCreateMutable(NULL,0);char *copy=strdup(text),*save=NULL,*line;for(line=strtok_r(copy,"\n",&save);line;line=strtok_r(NULL,"\n",&save)){int level=0;while(line[level]=='#')level++;const char *body=line+level;while(*body==' ')body++;CFStringRef part=CFStringCreateWithCString(NULL,body,kCFStringEncodingUTF8);if(!part)continue;CFIndex offset=CFAttributedStringGetLength(attr);CFAttributedStringReplaceString(attr,CFRangeMake(offset,0),part);CFAttributedStringReplaceString(attr,CFRangeMake(CFAttributedStringGetLength(attr),0),CFSTR("\n\n"));CFIndex length=CFAttributedStringGetLength(attr)-offset;CTFontRef linefont=level?CTFontCreateWithName(CFSTR("Helvetica-Bold"),level==1?20:14,NULL):font;CFAttributedStringSetAttribute(attr,CFRangeMake(offset,length),kCTFontAttributeName,linefont);if(level)CFRelease(linefont);CFRelease(part);}free(copy);CTFramesetterRef setter=CTFramesetterCreateWithAttributedString(attr);CGPathRef box=CGPathCreateWithRect(CGRectMake(45,45,505,752),NULL);CFIndex start=0,len=CFAttributedStringGetLength(attr);int pages=0;
 while(start<len&&pages++<200){CGContextBeginPage(ctx,&media);CTFrameRef frame=CTFramesetterCreateFrame(setter,CFRangeMake(start,0),box,NULL);CFRange visible=CTFrameGetVisibleStringRange(frame);CTFrameDraw(frame,ctx);CFRelease(frame);CFStringRef footer=CFStringCreateWithFormat(NULL,NULL,CFSTR("Sistema Escolar  |  Página %d"),pages);const void *fk[]={kCTFontAttributeName};const void *fv[]={font};CFDictionaryRef fa=CFDictionaryCreate(NULL,fk,fv,1,&kCFTypeDictionaryKeyCallBacks,&kCFTypeDictionaryValueCallBacks);CFAttributedStringRef fs=CFAttributedStringCreate(NULL,footer,fa);CTLineRef fl=CTLineCreateWithAttributedString(fs);CGContextSetTextPosition(ctx,45,22);CTLineDraw(fl,ctx);CFRelease(fl);CFRelease(fs);CFRelease(fa);CFRelease(footer);CGContextEndPage(ctx);if(visible.length<=0)break;start+=visible.length;}
 CGPDFContextClose(ctx);CGContextRelease(ctx);CGPathRelease(box);CFRelease(setter);CFRelease(attr);CFRelease(font);CFRelease(content);return start>=len;
}
cJSON *generate_files(cJSON *req){const char *base=str(req,"base"),*text=str(req,"text");if(!*base||strlen(base)>3500||strlen(text)>500000)return NULL;char path[4096];cJSON *out=cJSON_CreateObject();snprintf(path,sizeof path,"%s.md",base);if(!write_text(path,text))goto bad;cJSON_AddStringToObject(out,"markdown",path);
 snprintf(path,sizeof path,"%s.pdf",base);if(!pdf(path,text))goto bad;cJSON_AddStringToObject(out,"pdf",path);
 if(cJSON_IsTrue(cJSON_GetObjectItem(req,"notebook"))){cJSON *nb=cJSON_CreateObject(),*cells=array(),*cell=cJSON_CreateObject(),*meta=cJSON_CreateObject(),*kernel=cJSON_CreateObject();cJSON_AddNumberToObject(nb,"nbformat",4);cJSON_AddNumberToObject(nb,"nbformat_minor",5);cJSON_AddStringToObject(kernel,"display_name","Python 3");cJSON_AddStringToObject(kernel,"language","python");cJSON_AddStringToObject(kernel,"name","python3");cJSON_AddItemToObject(meta,"kernelspec",kernel);cJSON_AddItemToObject(nb,"metadata",meta);cJSON_AddItemToObject(nb,"cells",cells);
 cJSON_AddStringToObject(cell,"id","objetivo");cJSON_AddStringToObject(cell,"cell_type","markdown");cJSON_AddItemToObject(cell,"metadata",cJSON_CreateObject());cJSON_AddStringToObject(cell,"source","# Práctica: valor presente neto\nObjetivo: calcular y comparar proyectos con flujos de efectivo.\nDatos sintéticos; sustituye los valores y justifica tu decisión.");push(cells,cell);
 cell=cJSON_CreateObject();cJSON_AddStringToObject(cell,"id","calculo");cJSON_AddStringToObject(cell,"cell_type","code");cJSON_AddItemToObject(cell,"metadata",cJSON_CreateObject());cJSON_AddNullToObject(cell,"execution_count");cJSON_AddItemToObject(cell,"outputs",array());cJSON_AddStringToObject(cell,"source","def vpn(tasa, flujos):\n    return sum(flujo / (1 + tasa) ** t for t, flujo in enumerate(flujos))\n\nflujos = [-10000, 3500, 4000, 4500]\ntasa = 0.10\nresultado = vpn(tasa, flujos)\nassert round(vpn(0, [-10, 5, 5]), 6) == 0\nprint(f'VPN: {resultado:.2f}')\nprint('Proyecto aceptable' if resultado > 0 else 'Revisar proyecto')\n");push(cells,cell);
 cell=cJSON_CreateObject();cJSON_AddStringToObject(cell,"id","conclusiones");cJSON_AddStringToObject(cell,"cell_type","markdown");cJSON_AddItemToObject(cell,"metadata",cJSON_CreateObject());cJSON_AddStringToObject(cell,"source","## Conclusiones\nCompara tasas del 5%, 10% y 15%. Explica sensibilidad, supuestos y limitaciones.\n## Referencias\nUsa únicamente las referencias verificadas del reporte adjunto.");push(cells,cell);
 if(!strcmp(str(req,"kind"),"statistics")){cJSON *first=cJSON_GetArrayItem(cells,0),*code=cJSON_GetArrayItem(cells,1);cJSON_ReplaceItemInObject(first,"source",cJSON_CreateString("# Práctica: análisis descriptivo\nObjetivo: calcular métricas y comparar grupos con datos sintéticos.\nDocumenta supuestos, faltantes y límites de inferencia."));cJSON_ReplaceItemInObject(code,"source",cJSON_CreateString("import statistics\nfrom collections import Counter\n\nvalores = [5, 4, 3, 5, 2, 4, 5, 3, 4, 5]\nassert all(1 <= x <= 5 for x in valores)\nprint('Distribución:', dict(Counter(valores)))\nprint('Promedio:', statistics.mean(valores))\nprint('Mediana:', statistics.median(valores))\nprint('Varianza muestral:', statistics.variance(valores))\nfor nombre, grupo in [('A', valores[:5]), ('B', valores[5:])]:\n    print(nombre, statistics.mean(grupo))\n"));cJSON_ReplaceItemInObject(cJSON_GetArrayItem(cells,2),"source",cJSON_CreateString("## Conclusiones\nCompara los grupos A y B. Explica cómo cambiarían tus resultados con datos faltantes. No infieras causalidad a partir de promedios.\nUsa las referencias verificadas del reporte adjunto."));}
 char *json=cJSON_Print(nb);snprintf(path,sizeof path,"%s.ipynb",base);int good=json&&write_text(path,json);free(json);cJSON_Delete(nb);if(!good)goto bad;cJSON_AddStringToObject(out,"notebook",path);
 }return out;
 bad:cJSON_Delete(out);snprintf(failure,sizeof failure,"No se pudo generar el reporte");return NULL;}
